def longest_decreasing_run(lst):
    if not lst:
        return 0
    best = cur = 1
    for i in range(1, len(lst)):
        if lst[i] < lst[i-1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

def has_no_triple_repeated_chars(s):
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
            if count >= 3:
                return False
        else:
            count = 1
    return True

def count_vowels_per_word(words):
    vowels = set("aeiouAEIOU")
    d = {}
    for w in words:
        d[w] = sum(1 for ch in w if ch in vowels)
    return d

def indent_except_first(text, n):
    lines = text.split("\n")
    return "\n".join(line if i == 0 else " " * n + line for i, line in enumerate(lines))

def are_pairwise_coprime(nums):
    def g(a, b):
        a, b = abs(a), abs(b)
        while b:
            a, b = b, a % b
        return a
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            if g(nums[i], nums[j]) != 1:
                return False
    return True

def merge_concat_lists(d1, d2):
    res = {}
    for k in set(d1) | set(d2):
        if k in d1 and k in d2:
            res[k] = list(d1[k]) + list(d2[k])
        elif k in d1:
            res[k] = list(d1[k])
        else:
            res[k] = list(d2[k])
    return res

def count_divisible_by_any(n, divisors):
    count = 0
    for x in range(1, n + 1):
        if any(x % d == 0 for d in divisors):
            count += 1
    return count

def is_valid_camel_case(s):
    if not s or not (s[0].isalpha() and s[0].islower()):
        return False
    return all(c.isalnum() for c in s)

def symmetric_difference_preserve_order(a, b):
    set_a, set_b = set(a), set(b)
    seen = set()
    out = []
    for x in a:
        if x not in set_b and x not in seen:
            seen.add(x)
            out.append(x)
    for x in b:
        if x not in set_a and x not in seen:
            seen.add(x)
            out.append(x)
    return out

def compress_consecutive_ranges(lst):
    if not lst:
        return []
    out = []
    start = prev = lst[0]
    for x in lst[1:]:
        if x == prev + 1:
            prev = x
        else:
            out.append([start, prev])
            start = prev = x
    out.append([start, prev])
    return out

def mask_string(s, visible):
    if len(s) <= 2 * visible:
        return s
    return s[:visible] + '*' * (len(s) - 2 * visible) + s[len(s)-visible:]

def countdown_to_multiple_targets(current_hhmm, targets_list):
    ch, cm = map(int, current_hhmm.split(":"))
    cur = ch * 60 + cm
    best = None
    for t in targets_list:
        th, tm = map(int, t.split(":"))
        tar = th * 60 + tm
        diff = tar - cur
        if diff < 0:
            diff += 1440
        if best is None or diff < best:
            best = diff
    return best

def kth_smallest_using_merge(a, b, k):
    i = j = 0
    count = 0
    while True:
        if i < len(a) and (j >= len(b) or a[i] <= b[j]):
            count += 1
            if count == k:
                return a[i]
            i += 1
        else:
            count += 1
            if count == k:
                return b[j]
            j += 1

def remove_nth_word(s, n):
    words = s.split()
    if 0 <= n < len(words):
        del words[n]
    return ' '.join(words)

def digit_product(n):
    p = 1
    for d in str(abs(n)):
        p *= int(d)
    return p

def format_duration(seconds):
    h, rem = divmod(seconds, 3600)
    m, s = divmod(rem, 60)
    if h > 0:
        return f"{h}:{m:02d}:{s:02d}"
    return f"{m}:{s:02d}"

def sum_durations(durations):
    total = 0
    for d in durations:
        h, m = d.split(':')
        total += int(h)*60 + int(m)
    return f'{total//60:02d}:{total%60:02d}'

def flatten_nested_dict(nested):
    res = {}
    def rec(d, prefix):
        for k, v in d.items():
            key = f"{prefix}.{k}" if prefix else str(k)
            if isinstance(v, dict):
                rec(v, key)
            else:
                res[key] = v
    rec(nested, "")
    return res

def render_numbered_padded(items):
    n = len(items)
    width = len(str(n)) if n > 0 else 1
    return "\n".join(f"{str(i + 1).zfill(width)}. {item}" for i, item in enumerate(items))

def mask_phone_middle(digits):
    if len(digits) <= 5:
        return "*" * len(digits)
    return digits[:3] + "*" * (len(digits) - 5) + digits[-2:]

def flatten_deep(nested):
    out = []
    for x in nested:
        if isinstance(x, list):
            out.extend(flatten_deep(x))
        else:
            out.append(x)
    return out

def min_absolute_difference_pair(lst):
    s = sorted(lst)
    return min(s[i + 1] - s[i] for i in range(len(s) - 1))

def format_list_with_and(items):
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f", and {items[-1]}"

def is_prime(n):
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def format_accounting(amount):
    if amount == 0:
        return "$0.00"
    if amount < 0:
        return f"(${-amount:,.2f})"
    return f"${amount:,.2f}"

def smallest_with_exactly_d_divisors(d):
    n = 1
    while True:
        count = 0
        i = 1
        while i * i <= n:
            if n % i == 0:
                count += 1 if i * i == n else 2
            i += 1
        if count == d:
